\label{thm:Z-form}
Fix $P,L,N_0,\ldots, N_L\geq 1,\, \sigma^2>0$ as well as training data $X_{N_0},Y_{N_0}$. Fix ${\bf t}\in \mathbb R^{N_0}$ and write
\[
{\bf t} = {\bf t}_{||}+ {\bf t}_\perp,\qquad {\bf t}_{||}\in \mathrm{col}(X_{N_0}),\quad {\bf t}_{\perp}\in \mathrm{col}(X_{N_0})^\perp.
\]
Define $4M = \prod_{\ell=0}^L 2\sigma^2/N_\ell$



and introduce the following shorthand for the Meijer-G functions (see \S \ref{sec:back})                                                      
with parameters given by layer widths:
\begin{align*}
&\ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2},\frac{\mathbf{N}}{2}+k 
\end{array} \right)}:=\qquad\ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2},\frac{N_1}{2}+k,\ldots, \frac{N_L}{2}+k 
\end{array} \right)}.
\end{align*}
The partition function $Z_\infty({\bf t})$ of the predictive posterior defined in \eqref{eq:part-def} is
\begin{align}
&Z_\infty({\bf t}) =  \left(\frac{4\pi }{\left|\left|\theta_*\right|\right|^2}\right)^{\frac{P}{2}} \exp\left[-i\left \langle \theta_{*,N_0},{\bf t}\right\rangle \right]\prod_{\ell=1}^L \Gamma\left(\frac{N_\ell}{2}\right)^{-1} \nonumber\\
&\qquad \qquad \times \sum_{k=0}^\infty \frac{(-1)^k}{k!}\big|\big|{\bf t}_{\perp} \big|\big| ^{2k} M^{k} \ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2}, \frac{\bf{N}}{2}+k 
\end{array} \right)}.
\end{align}
In particular, the Bayesian model evidence $Z_\infty({\bf 0})$ equals
\begin{align}
\label{eq:evidence-form} \frac{(4\pi)^{P/2}}{\left|\left|\theta_*\right|\right|^{P}\prod_{\ell=1}^L \Gamma\left(\frac{N_\ell}{2}\right)} \ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2}, \frac{\bf{N}}{2} 
\end{array} \right)}.


\end{align}
Further, given $x\in \mathbb R^{N_0}$, the mean of the predictive posterior is
\begin{equation}\label{eq:mean-G}
\mathbb E_{\text{post}}\left[f(x)\right]= (\theta_{*,N_0})^Tx,
\end{equation}
while the posterior variance $\mathrm{Var}_{\mathrm{post}}\left[f(x)\right]$ is 
\begin{equation}\label{eq:var-G}
2M\left|\left|x_{\perp}\right|\right|^2\frac{\ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2}, \frac{\bf{N}}{2}+1 
\end{array} \right)}}{\ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2}, \frac{\bf{N}}{2} 
\end{array} \right)}},    
\end{equation}
where $x_\perp$ is the projection of $x$ onto the orthogonal complement of the span $\mathrm{col}(X_{N_0})$ of the training data.

\label{thm:logG}
Set $N_1,\ldots,N_L = N$ and define $\mathbf{N} = (N_1, \dots, N_L)$. Suppose that the training data satisfies \eqref{eq:Vstar-def}. In different limiting cases such that $\{P, N\} \to \infty$ with fixed $P/N_0 = \alpha_0$, we evaluate the quantities
\begin{align*}
    \log G &:= \log \ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2},\frac{\mathbf{N}}{2}+k 
\end{array} \right)}\\
    \Delta(\log G)[k] &:= \log \ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2},\frac{\mathbf{N}}{2}+k 
\end{array} \right)} - \log \ensuremath{G_{0,L+1}^{L+1,0}\left( \frac{\left|\left|\theta_{*,N_0}\right|\right|^2}{4M} ~\bigg| \begin{array}{c}
     -  \\
     \frac{P}{2},\frac{\mathbf{N}}{2} 
\end{array} \right)}.
\end{align*}
We will see in each case that to leading order $\log G$ does not depend on $k$ while $ \Delta(\log G)[k] $ does.
\begin{enumerate}[label=(\alph*)]
\item Fix $L < \infty,\, \alpha,\sigma^2>0$. Suppose $P,N\rightarrow \infty$ with $P/N\rightarrow \alpha$. Then,





\begin{align}
    \notag \log G &= \frac{N\alpha}{2}\left[\log\left(\frac{N\alpha}{2}\right) + \log\left(1+\frac{z_*}{\alpha}\right) - \left(1+\frac{z_*}{\alpha}\right)\right] \nonumber \\
    &\label{eq:logG-Lfinite}\quad + \frac{NL}{2}\left[\log\left(\frac{N}{2}\right) + \log\left(1+z_*\right) - (1+z_*)\right]
\end{align}
plus an error of size $\tilde O(1)$ and
\begin{align}
    \label{eq:DlogG-Lfinite} \Delta(\log G)[k] &= kL\left[\log\left(\frac{N}{2}\right) + \log(1+z_*)\right],
\end{align}



plus an error of size $\tilde O\left(1/N\right)$, where $z_*> \min\left\{-\alpha,-1\right\}$ is the unique solution to
\begin{equation}\label{eq:Psi-crit}
\left(1+\frac{z_*}{\alpha}\right)\left(1+z_*\right)^L = \frac{\left|\left|\theta_*\right|\right|^2}{\sigma^{2(L+1)}\alpha_0}.
\end{equation} 
\item Fix $\lambda_{\mathrm{prior}},\alpha>0$ and suppose $L=\lambda_{\mathrm{prior}} N, \, P,N\rightarrow \infty,\, P/N\rightarrow \alpha, \, \sigma^2=1$. Then,
\begin{align}
    \label{eq:logG-LN} \log G &= \frac{\lambda_{\mathrm{prior}} N^2}{2}\left[\log\left(\frac{N}{2}\right) - 1\right] + \frac{N\alpha}{2}\left[\log\left(\frac{N\alpha}{2}\right) - 1\right]\\
    &\quad + \frac{\lambda_{\mathrm{prior}} N}{2}\left[-\log\left(\frac{N}{2}\right) + \log(2\pi)\right]  + \tilde O(1)\nonumber
\end{align}
and, up to an error of size $\tilde O\left(1/N\right)$, 
\begin{align}
    \label{eq:DlogG-LN} \Delta(\log G)[k] &= k\left[\lambda_{\mathrm{prior}} N \log\left(\frac{N}{2}\right) + \log \left(\frac{\left|\left|\theta_*\right|\right|^2}{\alpha_0}\right)\right].
\end{align}




\item Fix $\lambda_{\mathrm{post}} >0$. Suppose $N,P,L\rightarrow \infty$ with $LP/N\rightarrow \lambda_{\mathrm{post}}, \, \sigma^2=1$ and $L/N\to 0$. Then,
\begin{align}
    \label{eq:logG-PLN} \log G &= \frac{P}{2}\left[\log\left(\frac{P}{2}\right)-1\right] + \frac{\lambda_{\mathrm{post}} N}{2}\frac{N}{P}\left[\log\left(\frac{N}{2}\right)-1\right] \nonumber \\
    &\quad + \frac{P}{2}\left[\log(1+t_*)-t_*\left(1+\frac{\lambda_{\mathrm{post}} t_*}{2}\right)\right] \nonumber \\
    &\quad + \frac{\lambda_{\mathrm{post}} N}{2}\left[\frac{N}{P}\left(1+\frac{P}{N}t_*\right)\log\left(1+\frac{P}{N}t_*\right) - t_*\right] \nonumber\\
    &\quad + \tilde O(1),
\end{align}
and
\begin{align}
    \label{eq:DlogG-PLN}   \Delta(\log G)[k] &= k\left[L \log \left(\frac{N}{2}\right) + \lambda_{\mathrm{post}} t_*\right] + \tilde{O}\left(\frac{1}{N}\right),
\end{align}
where $t_*$ is the unique solution to
\begin{align}
    e^{\lambda_{\mathrm{post}} t_*}(1+t_*) &= \left|\left|\theta_*\right|\right|^2/\alpha_0.
\end{align}
\end{enumerate}
In all the estimates above, $\tilde O(1) = O(\max\{\log P, \log N\})$ suppresses lower-order terms of order 1, up to logarithmic factors; similarly, $\tilde O(1/N) = O(\max\{\log P, \log N\}/N)$. Suppressed terms are included in \S \ref{pf:logG}

\label{thm:bayesfeature}
Fix $L, N_1\dots, N_L \geq 1$, $\sigma^2 > 0$, $\alpha_0\in (0,1)$, and consider sequences of training data sets $X_{N_0}\in \mathbb R^{N_0\times P}, Y_{N_0}\in \mathbb R^{1\times P}$ such that
\begin{align*}
    P, N_0 \to \infty, \qquad P/N_0 \to \alpha_0
\end{align*}
and \eqref{eq:Vstar-def} holds. Let $Z_\infty({\bf 0})$ denote the limiting Bayesian model evidence. The following statements are equivalent:
\begin{enumerate}[label=(\alph*)]
    \item $\sigma^2$ maximizes $Z_\infty({\bf 0})$, and
    \item the posterior over predictions $f(x)$ converges weakly to a Gaussian $\mathcal{N}\left(\mu_*, \nu \Sigma_\perp\right)$.
\end{enumerate}

\label{thm:finite-L}
For each $N_0,P\geq 1$, consider training data $X_{N_0},Y_{N_0}$ satisfying \eqref{eq:Vstar-def}. Fix constants $L\geq 0,\,\sigma^2 > 0$ and suppose that
\begin{equation*}
P,N_0,N \rightarrow \infty,\quad P/N_0 \rightarrow \alpha_0\in (0,1),\quad P/N\rightarrow \alpha\in (0,\infty). 
\end{equation*}
In this limit, the posterior over predictions $f(x)$ converges weakly to a Gaussian
\begin{align*}
\mathcal{N}\left(\mu_*,~\nu\Sigma_\perp\left(1+\frac{z_*}{\alpha}\right)^{-1}\right),
\end{align*}
where $z_*$ is the unique solution to
\begin{equation}\label{eq:zstar}
\frac{\nu}{\sigma^{2(L+1)}} = \left(1+\frac{z_*}{\alpha}\right)\left(1+z_*\right)^L,\quad z_* > \max\left\{-1,-\alpha\right\}.
\end{equation}
Additionally, we have the following large-$P$ expansion of the Bayesian model evidence
\begin{align*}
\log Z_\infty({\bf 0}) &~\rightarrow~ \frac{P}{2}\Bigg[\log\left(\frac{P}{2}\right) + \log\left(1+\frac{z_*}{\alpha}\right) - \left(1+\frac{z_*}{\alpha}\right) \nonumber \\
&\quad - \log\left(\frac{\left|\left|\theta_*\right|\right|^2}{4\pi}\right)\Bigg] + \frac{NL}{2}\left[\log\left(1+z_*\right) - z_*\right] \nonumber\\
&\quad + O(\max\left\{\log P, \log N\right\}).
\end{align*}

\label{cor:Lfix-evid}
In the setting of Theorem \ref{thm:finite-L}  the Bayesian evidence $Z_\infty({\bf 0})$ satisfies: 
\begin{align}
\label{eq:sig-star}\sigma_*^2 &= \operatorname*{arg\,max}_{\sigma}Z_\infty({\bf 0}) = \nu^{\frac{1}{L+1}}\\
\label{eq:L-star} L_* &= \operatorname*{arg\,max}_{L}Z_\infty({\bf 0}) =\frac{\log(\nu)}{\log(\sigma^2)}-1.
\end{align}
In particular, given a prior variance with $\mathrm{sgn}\left(\nu-1\right)=\mathrm{sgn}\left(\sigma^2-1\right)$ satisfying $|\sigma^2-1| \leq \epsilon$, the optimal depth network satisfies $L_* \geq |\log(\nu)|/\epsilon$.

\label{thm:LN}
For each $N_0,P\geq 1$, consider training data $X_{N_0},Y_{N_0}$ satisfying \eqref{eq:Vstar-def}. Moreover, fix $\lambda_{\mathrm{prior}},\alpha \in (0,\infty),\, \alpha_0\in (0,1).$ Suppose that $N_1=\cdots=N_L=N$ and that
\begin{equation*}
P,N_\ell,L\rightarrow \infty,\quad P/N_0\rightarrow \alpha_0,\quad P/N\rightarrow \alpha,\quad L/N\rightarrow \lambda_{\mathrm{prior}}.
\end{equation*}
In this limit, the posterior over predictions $f(x)$ converges weakly to a Gaussian
\begin{align*}
\mathcal{N}\left(\mu_*,~\nu\Sigma_\perp\right),
\end{align*}
which is independent of $\alpha,\lambda_{\mathrm{prior}}$. Additionally, the evidence admits the following asymptotic expansion:
\begin{align*}
\log Z_\infty({\bf 0}) &= \frac{P}{2}\left[\log\left(\frac{P}{2}\right) - 1 - \log\left(\frac{\left|\left|\theta_*\right|\right|^2}{4\pi}\right)\right] + O(\max\left\{\log P, \log N\right\}).
\end{align*}

\label{cor:feature-learning}
In the setting of Theorem \ref{thm:LN}, the posterior distribution over regression weights $\theta$ is the same in the following two settings:
\begin{itemize}
	\item We fix $L\geq 0$, take the data-dependent prior variance $\sigma_*$ that maximizes the Bayesian model evidence as a function of the training data and network depth as in \eqref{eq:sig-star}, and send the network width $N$ to infinity.
	\item We fix $\lambda_{\mathrm{prior}} >0$, take a data-agnostic prior $\sigma^2=1$, and send both the network depth $L:=\lambda_{\mathrm{prior}} \cdot N$ and network width $N$ to infinity together.
\end{itemize}

\label{thm:PLN}
For each $N_0,P\geq 1$, consider training data $X_{N_0},Y_{N_0}$ satisfying \eqref{eq:Vstar-def}. Moreover, fix constants $\lambda_{\mathrm{post}} > 0,\, \alpha_0\in (0,1), \, \sigma^2=1$. Suppose that $N_1=\cdots = N_L=N$ and suppose that
\begin{align*}
P, N_\ell, L \to \infty, \; \frac{P}{N_0} \to \alpha_0 , \; \frac{P}{N} \to 0, \; \frac{L}{N} \to 0, \; \frac{LP}{N} \to \lambda_{\mathrm{post}}.
\end{align*}
In this limit, the posterior over predictions $f(x)$ converges weakly to a Gaussian $\mathcal{N}\left(\mu_*,~\nu\Sigma_\perp(1+t_*)^{-1}\right)$,



where $t_*$ is the unique solution to
\begin{align*}
    \nu = (1+t_*)e^{\lambda_{\mathrm{post}} t_*}, \quad t_* > -1.
\end{align*}
Additionally, we have the following asymptotic expansion for the Bayesian model evidence
\begin{align*}
    \log Z_\infty({\bf 0}) &= \frac{P}{2}\left(\log\left(\frac{P}{2}\right)-1\right) - \frac{P}{2} \log\left(\frac{\left|\left|\theta_*\right|\right|^2}{4\pi}\right)\\
    &\quad + \frac{P}{2}\left[\log(1+t_*)-t_* - \frac{1}{2}\lambda_{\mathrm{post}} t_*^2\right] + \tilde O(\max\left\{\log P, \log N, \log L\right\}).
\end{align*}

In the setting of Theorem~\ref{thm:PLN}, the Bayesian evidence $Z_\infty({\bf 0})$ is monotonically increasing in $\lambda_{\mathrm{post}}$. Specifically,
\begin{align}
\frac{\partial \log Z_\infty({\bf 0})}{\partial \lambda_{\mathrm{post}}} = \frac{Pt_*^2}{4} \geq 0.
\end{align}

\label{thm:scaling}
For each $N_0\geq 1$ consider training data $X_{N_0},Y_{N_0}$ satisfying \eqref{eq:Vstar-def}. Fix constants $\lambda_{\mathrm{prior}} > 0,\alpha>0, \, \sigma^2=1$. Suppose that $N_1=\cdots=N_L= N$, that $L=\lambda_{\mathrm{prior}} N$ and number of data points satisfies $P=N\alpha$. Then, as $N\rightarrow \infty$,
\begin{align*}
    \mathrm{Var}_{\mathrm{post}}\left[f(x)\right] = \lim_{N\to\infty} \mathrm{Var}_{\mathrm{post}}\left[f(x)\right] +\frac{C}{N}+O\left(\frac{\log N}{N^2}\right),                                                             
\end{align*}
where $C\in \mathbb R$ is a universal constant.

\label{prop:gamma-exp}
We have the following analytic asymptotic expansion for the Gamma function
\begin{equation}\label{eq:Gamma-exp}
\log \Gamma\left(z\right) \sim \left(z-\frac{1}{2}\right)\log(z) - z + \text{const}+O\left(\left|z\right|^{-1}\right),\quad \text{as }\left|z\right|\rightarrow \infty.
\end{equation}
In particular, we also have
\begin{equation}\label{eq:diGamma-exp}
\phi^{(1)}(z)=\frac{d}{dz}\log \Gamma\left(z\right) \sim \log(z) + O(\left|z\right|^{-1}),\quad \text{as }\left|z\right|\rightarrow \infty.
\end{equation}
Both expansions hold uniformly on sets of the form $\left|z\right|< \pi - \delta$ for a fixed $\delta >0$.

Let $k,\theta >0$ and suppose $\phi \sim \Gamma(k,\theta)$. Then for any $t\in \mathbb R$ we have
\begin{equation}\label{E:gamma-moments}
\mathbb E\left[\phi^t\right] = \theta^t\frac{\Gamma\left(k+t\right)}{\Gamma\left(k\right)}.    
\end{equation}
In particular
\begin{equation}\label{E:gamma-MGF}
\mathbb E\left[e^{-it \log\phi}\right] = \exp\left[-it\log \theta + \log \Gamma\left(k-it\right)-\log \Gamma(k)\right]     
\end{equation}
is a meromorphic function of $t$ with poles on the negative imaginary axis:
\[
t = -i(\nu +k),\quad \nu = 0,1,2,\ldots.
\]

For $\eta,\omega>0$, We have
\begin{align}
\label{E:G-cancel}  & \ensuremath{G_{p,q}^{m,n}\left( x ~\bigg| \begin{array}{c}
     \alpha,{\bf a}  \\
     {\bf b},\alpha 
\end{array} \right)} =\ensuremath{G_{p-1,q-1}^{m,n-1}\left( x ~\bigg| \begin{array}{c}
     {\bf a}  \\
     {\bf b} 
\end{array} \right)}  \\
  \label{E:G-weighted-Laplace}  &\int_0^\infty e^{-\omega x} x^{-\alpha} \ensuremath{G_{p,q}^{m,n}\left( \eta x ~\bigg| \begin{array}{c}
     {\bf a}  \\
     {\bf b} 
\end{array} \right)} dx=\omega^{\alpha-1} \ensuremath{G_{p+1,q}^{m,n+1}\left( \frac{\eta}{\omega} ~\bigg| \begin{array}{c}
     \alpha, {\bf a}  \\
     {\bf b} 
\end{array} \right)} \\
  \label{E:G-inversion}&\ensuremath{G_{p,q}^{m,n}\left( z ~\bigg| \begin{array}{c}
     {\bf a}  \\
     {\bf b} 
\end{array} \right)} =\ensuremath{G_{q,p}^{n,m}\left( z^{-1} ~\bigg| \begin{array}{c}
     1-{\bf b}  \\
     1-{\bf a} 
\end{array} \right)}\\
  \label{E:G-polyprod}&z^\rho \ensuremath{G_{p,q}^{m,n}\left( z ~\bigg| \begin{array}{c}
     {\bf a}  \\
     {\bf b} 
\end{array} \right)} =\ensuremath{G_{p,q}^{m,n}\left( z ~\bigg| \begin{array}{c}
     \rho+{\bf a}  \\
     \rho+{\bf b} 
\end{array} \right)}\\
  \label{E:G-BesselJ} &\ensuremath{G_{0,2}^{1,0}\left( \frac{x^2}{4} ~\bigg| \begin{array}{c}
     -  \\
     \frac{\nu}{2}, -\frac{\nu}{2} 
\end{array} \right)}= J_{\nu}(x)\\
  \label{E:G-deriv}
  &z^h \frac{d^h}{dz^h}\ensuremath{G_{p,q}^{m,n}\left( z ~\bigg| \begin{array}{c}
     {\bf a}  \\
     {\bf b} 
\end{array} \right)} = \ensuremath{G_{p+1,q+1}^{m,n+1}\left( z ~\bigg| \begin{array}{c}
     {0, \bf a}  \\
     {\mathbf{b}, h} 
\end{array} \right)}\\
  \label{E:G-conv}
  &\int_0^\infty \ensuremath{G_{p,q}^{m,n}\left( \eta x ~\bigg| \begin{array}{c}
     \mathbf a  \\
     \mathbf b 
\end{array} \right)} \ensuremath{G_{\sigma, \tau}^{\mu, \nu}\left( \omega x ~\bigg| \begin{array}{c}
     \mathbf c  \\
     \mathbf d 
\end{array} \right)} dx = \frac{1}{\eta}\ensuremath{G_{q+\sigma,p+\tau}^{n+\mu,m+\nu}\left( \frac{\omega}{\eta} ~\bigg| \begin{array}{c}
     -b_1,\dots,-b_m, \mathbf c, -b_{m+1},\dots,-b_q  \\
     -a_1,\dots,-a_n, \mathbf d, -a_{n+1},\dots,-a_p 
\end{array} \right)}\\
 \label{E:G-series} &\int_0^\infty \tau^{\alpha-1}\ensuremath{G_{u,v}^{s,t}\left( \sigma+\tau ~\bigg| \begin{array}{c}
     c_1,\ldots,c_u  \\
     d_1,\ldots, d_v 
\end{array} \right)} \ensuremath{G_{p,q}^{m,n}\left( \omega \tau ~\bigg| \begin{array}{c}
     a_1,\ldots, a_p  \\
     b_1,\ldots, b_q 
\end{array} \right)}d\tau  \\
 \notag &= \sum_{k=0}^\infty \frac{\left(-\sigma\right)^k}{k!} \ensuremath{G_{p+v+1,q+u+1}^{m+t,n+s+1}\left( \omega  ~\bigg| \begin{array}{c}
     1-\alpha,a_1,\ldots, a_n, k-\alpha-d_1+1,\ldots, k-\alpha-d_v+1,a_{n+1},\ldots, a_p  \\
     b_1,\ldots, b_m, k-\alpha-c_1+1,\ldots, k-\alpha-c_u+1, k-\alpha+1, b_{m+1},\ldots, b_q 
\end{array} \right)}

\end{align}
For \eqref{E:G-series} we require
\[
\left|\arg(\sigma)\right|, \left|\arg(\omega)\right|<\pi
\]
and
\[
-\min\left\{\Re(b_1),\ldots, \Re(b_m)\right\}
< \Re(\alpha)<2 - \max\left\{\Re(a_1),\ldots, \Re(a_n)\right\}- \max\left\{\Re(c_1),\ldots, \Re(c_t)\right\}.
\]
Finally, fix $L\geq 1$ and 
\[
k_\ell, \theta_\ell >0,\qquad \ell=1,\ldots, L
\]
and let 
\[
\phi_\ell \sim \Gamma\left(k_\ell,\theta_\ell\right)  \quad \text{independent}.
\]
We have for every $y>0$
\begin{align}
    \label{eq:G-gamma} \prod_{\ell=1}^L \Gamma\left(k_\ell\right)^{-1 } \frac{1}{A}\ensuremath{G_{0,L}^{L,0}\left( \frac{y}{A} ~\bigg| \begin{array}{c}
     -  \\
     k_1-1,\ldots, k_L-1 
\end{array} \right)} = \mathrm{Den}_{\prod_{\ell=1}^L\phi_\ell}(y),\qquad A:=\prod_{\ell=1}^L \theta_\ell.
\end{align}

\label{lem:normal}
For each $N_0$, consider a collection of $k\geq 1$ test points
\[
{\bf x}_{N_0} = \left(x_{j;N_0},\,j=1,\ldots,k\right).
\]
Suppose that 
\begin{itemize}
    \item For each $\alpha_0\in (0,1)$ there exists a vector $\mu_{*}=\left(\mu_{*,j},\, j=1,\ldots,  k\right)\in \mathbb R^k$ such that
    \begin{equation}\label{eq:mu-def}
    \lim_{\substack{P,N_0\rightarrow \infty \\ P/N_0\rightarrow \alpha_0\in (0,1)}}\left \langle \theta_{*,N_0},x_{j,N_0}\right\rangle  =  \mu_{*,j}\qquad \text{ almost surely}.    
    \end{equation}
    \item For each $\alpha_0\in (0,1)$ there exists a positive semi-definite $k\times k$ matrix $\Sigma_\perp$ such that
    \begin{equation}\label{eq:Sig-def}
        \lim_{\substack{P,N_0\rightarrow \infty \\ P/N_0\rightarrow \alpha_0\in (0,1)}} \left(\frac{1}{N_0-P}\left \langle x_{i,N_0}^\perp,x_{j,N_0}^\perp\right\rangle \right)_{1\leq i,j\leq k} = \Sigma_\perp\qquad \text{ almost surely},
    \end{equation}
    where $x_{j,N_0}^\perp$ denotes the projection of $x_j$ onto the orthogonal complement of the column space of $X_{N_0}$. 
\end{itemize}
Assume that the convergence of the posterior for $\left|\left|\theta_\perp\right|\right|^2$ in the large-$N$ limit satisfies
\begin{align*}
\left|\left|\theta_\perp\right|\right|^2 \to \nu(1-\alpha_0)c
\end{align*}
for some constant $c$. Then the distribution over posterior predictions evaluated on ${\bf x}_{N_0}$
\[
f({\bf x}_{N_0}) = \left(a^Tx_{j,N_0},\, j=1,\ldots, k\right),\qquad \theta\sim \mathbb P_{\mathrm{post}}
\]
converges weakly to a $k$-dimensional Gaussian: 
\begin{align}
\label{eq:normal-post}f({\bf x}_{N_0}) ~\rightarrow~ \mathcal N\left(\mu_*, ~ \nu c\Sigma_{\perp}\right).
\end{align}

\label{prop:Z-gen}
For any $\beta > 0$, the partition function $Z_\beta(x)$ equals
\begin{align*}
&\prod_{\ell=1}^L\Gamma\left(\frac{N_\ell}{2}\right)^{-1} \exp\left[-i\theta_*^Tx_{||}\right]\\ &\qquad \times \int_{\mathrm{col}{(X)}} d\zeta\exp\left[-\frac{\left|\left|X^{\dagger}(\tau - x_{||})\right|\right|^2}{2\beta}+i\theta_*^T\zeta\right]~ \ensuremath{G_{L,1}^{1,L}\left( M\left|\left|\zeta\right|\right|^2 +M\left|\left|x_\perp\right|\right|^2 ~\bigg| \begin{array}{c}
     1-\frac{{\bf N}}{2}  \\
     0 
\end{array} \right)},
\end{align*}
where $X^{\dagger}$ is the pseudo-inverse of $X$ and 
\[
4M = \prod_{\ell=0}^L \frac{2\sigma^2}{N_\ell}.
\]

We begin the proof of Proposition \ref{prop:Z-gen} by integrating out the final layer weights $W^{(L+1)}$ and introducing a dual variable $t\in \mathbb R^{P}$, as in the following.


\begin{lemma}\label{L:partition-form}
Write
\[
X^L:=W^{(L)}\cdots W^{(1)} X,\qquad x^L =W^{(L)}\cdots W^{(1)} x.
\]
We have
\begin{equation}\label{E:Z-noa}
Z_\beta(x) =\det(X^TX)^{1/2}\int_{\mathbb R^P} \mathbb E_{\mathrm{prior}}\left[\exp\left[-\frac{\left|\left|t\right|\right|_2^2}{2\beta}+i\theta_*^TXt-\frac{\sigma^2}{2N_L}\left|\left|X^Lt + x^L\right|\right|^2\right] \right]dt,
\end{equation}
\end{lemma}



\begin{proof}
From the following identity
\begin{align*}
   1= \int_{\mathbb R^P} \frac{dt}{(2\pi \beta)^{P/2}} \exp\left[-\frac{1}{2\beta} \left|\left|t^T- i\beta\left(\theta_*^TX-W^{(L+1)}X^L\right)\right|\right|^2\right] 
\end{align*}
we conclude
\begin{align*}
 & \exp\left[-\frac{\beta}{2}\left|\left|\theta_*^TX-W^{(L+1)}X^L\right|\right|^2\right]\\
  &\quad =  \int \frac{d t}{(2\pi \beta)^{P/2}} \exp\left[-\frac{1}{2\beta} \left|\left|t^T- i\beta\left(\theta_*^TX-W^{(L+1)} X^L\right)\right|\right|^2-\frac{\beta}{2}\left|\left|\theta_*^TX-W^{(L+1)} X^L\right|\right|^2\right] \\
  &\quad =\int \frac{d t}{(2\pi \beta)^{P/2}} \exp\left[-\frac{1}{2\beta} \left|\left|t\right|\right|^2 +it\left(\theta_*^TX-W^{(L+1)} X^L\right)\right].
\end{align*}
Substituting this into \eqref{eqsi:Z-form-1} we find
\begin{align*}
Z_\beta(x)&= \frac{A_{\beta}}{(2\pi \beta)^{P/2}} \int_{\mathbb R^P}\mathbb E_{\mathrm{prior}}\left[ \exp\left[i\left(\theta_*^TXt-W^{(L+1)}\left(X^Lt +x^L\right)\right) -\frac{\left|\left|t\right|\right|^2}{2\beta}\right]\right] dt    
\end{align*}
Now we compute the expectation over the final layer weights $W^{(L+1)}$ by completing the square:
\begin{align*}
    -\frac{N_L}{2\sigma^2}\left|\left|W^{(L+1)}\right|\right|_2^2 - iW^{(L+1)}\left(X^Lt + x^L\right)= &-\frac{N_L}{2\sigma^2}\left[\left|\left|W^{(L+1)}-i\frac{\sigma^2}{N_L}(X^Lt+x^L)\right|\right|_2^2\right]\\
    &- \frac{\sigma^2}{2N_L}\left|\left|X^Lt + x^L\right|\right|_2^2.
\end{align*}
This yields
\[
Z_\beta (x) =\frac{A_{\beta}}{(2\pi \beta)^{P/2}}\int_{\mathbb R^P}\mathbb E_{\mathrm{prior}}\left[ \exp\left[ -\frac{\left|\left|t\right|\right|^2}{2\beta}+i\theta_*^TXt-\frac{\sigma^2}{2N_L}\left|\left|X^Lt + x^L\right|\right|^2\right]\right]dt,

\]
 completing the proof.
\end{proof}



\noindent For each fixed $t$, note that
\[
X^Lt + x^L = W^{(L)}\cdots W^{(1)}\left(Xt + x\right).
\]
Hence, the expectation 
\[
\mathbb E_{\mathrm{prior}}\left[ \exp\left[-\frac{\sigma^2}{2N_L}\left|\left|X^Lt + x^L\right|\right|^2\right]\right]
\]
equals the Laplace transform 
\[
\mathcal L_{Q_{N,L}}\left(M'\left|\left|Xt+x\right|\right|^2\right)
\]
of the random variable
\begin{equation}\label{E:QNL-def}
Q_{N,L} = \left|\left| \left\{\prod_{\ell=1}^L \widehat{W}^{(\ell)}\right\} u\right|\right|^2,\qquad \widehat{W}^{(\ell)} \sim \mathcal N\left(0,I_{N_{\ell}\times N_{\ell-1}}\right)\text{ independent},    
\end{equation}
where $u$ is any unit vector (the distribution is the same for any $u$ since $W^1$ is rotationally invariant) evaluated at $\left|\left|Xt+x\right|\right|^2$ times 
\[
M' :=\frac{1}{2} \left(\prod_{\ell=1}^L \frac{\sigma^2}{N_\ell}\right) 
\]
Thus, we obtain 
\begin{equation}\label{E:Z-lap}
Z_\beta(x) =\det(X^TX)^{1/2} \int dt \exp\left[-\frac{\left|\left|t\right|\right|^2}{2\beta}+i\theta_*^TXt\right] \mathcal L_{Q_{N,L}}\left(M'\left|\left|Xt+x\right|\right|^2\right),
\end{equation}
To proceed we rewrite the Laplace transform in the preceding line in terms of a Meijer-G function.


\begin{lemma}\label{L:QNL-form}
Let $Q_{N,L}$ be defined as in \eqref{E:QNL-def}. Then, 
\begin{align*}
\mathcal L_{Q_{N,L}}\left(\tau\right)= \left(\prod_{\ell=1}^L \Gamma \left(\frac{N_\ell}{2}\right)\right)^{-1}~\ensuremath{G_{L,1}^{1,L}\left( 2^L\tau ~\bigg| \begin{array}{c}
     1-\frac{N_L}{2},\dots,1-\frac{N_1}{2}  \\
     0 
\end{array} \right)}.
\end{align*}
\end{lemma}


\begin{proof}
The density of $Q_{N,L}^{1/2}$ is known from \cite{zavatone2021exact}:
\[
p_{Q_{N,L}^{1/2}}(\rho) = \frac{2^{1-L/2}}{\Gamma\left(\frac{N_1}{2}\right)\cdots \Gamma\left(\frac{N_{L}}{2}\right)} \ensuremath{G_{0,L}^{L,0}\left( \frac{\rho^2}{2^L  } ~\bigg| \begin{array}{c}
     -  \\
     \frac{N_L-1}{2},\cdots, \frac{N_1-1}{2} 
\end{array} \right)}.
\]
Hence, the density of $\widehat{Q}_{N,L}$ is 
\begin{align*}
p_{Q_{N,L}}(\rho) &= \frac{1}{2\rho^{1/2}}  p_{Q_{N,L}}(\rho^{1/2})\\
&=\frac{2^{-L}}{\Gamma\left(\frac{N_1}{2}\right)\cdots \Gamma\left(\frac{N_{L}}{2}\right)} \left(\frac{2^L}{\rho}\right)^{1/2}\ensuremath{G_{0,L}^{L,0}\left( \frac{\rho}{2^L  } ~\bigg| \begin{array}{c}
     -  \\
     \frac{N_L-1}{2},\cdots, \frac{N_1-1}{2} 
\end{array} \right)}\\
&=\frac{2^{-L}}{\Gamma\left(\frac{N_1}{2}\right)\cdots \Gamma\left(\frac{N_{L}}{2}\right)} \ensuremath{G_{0,L}^{L,0}\left( \frac{\rho}{2^L  } ~\bigg| \begin{array}{c}
     -  \\
     \frac{N_L}{2}-1,\cdots, \frac{N_1}{2}-1 
\end{array} \right)},
\end{align*}
where in the last step we've used \eqref{E:G-polyprod}. Hence, 
\begin{align*}
    \mathcal L_{Q_{N,L}}(\tau) &= \int_0^\infty e^{-\tau \rho}  \ensuremath{G_{0,L}^{L,0}\left( \frac{\rho}{2^L  } ~\bigg| \begin{array}{c}
     -  \\
     \frac{N_L}{2}-1,\cdots, \frac{N_1}{2}-1 
\end{array} \right)} d\rho\\
    &=\left(\Gamma\left(\frac{N_1}{2}\right)\cdots \Gamma\left(\frac{N_{L}}{2}\right)\right)^{-1} \frac{1}{2^L\tau} \ensuremath{G_{1,L}^{L,1}\left( \frac{1}{2^L \tau } ~\bigg| \begin{array}{c}
     0  \\
     \frac{N_L}{2}-1,\cdots, \frac{N_1}{2}-1 
\end{array} \right)}\\
    &=\left(\Gamma\left(\frac{N_1}{2}\right)\cdots \Gamma\left(\frac{N_{L}}{2}\right)\right)^{-1} \ensuremath{G_{1,L}^{L,1}\left( \frac{1}{2^L \tau } ~\bigg| \begin{array}{c}
     0  \\
     \frac{N_L}{2},\cdots, \frac{N_1}{2} 
\end{array} \right)}\\
    &=\left(\Gamma\left(\frac{N_1}{2}\right)\cdots \Gamma\left(\frac{N_{L}}{2}\right)\right)^{-1}  \ensuremath{G_{L,1}^{1,L}\left( 2^L \tau  ~\bigg| \begin{array}{c}
     1-\frac{N_L}{2},\cdots, 1-\frac{N_1}{2}  \\
     0 
\end{array} \right)}
\end{align*}
where we've used \eqref{E:G-weighted-Laplace} and \eqref{E:G-inversion}.
\end{proof}


\noindent Combining the preceding Lemma with \eqref{E:Z-lap} gives
\begin{align}
\label{eqsi:ztilde-old}
    Z(x) &= \frac{\det(X^TX)^{1/2}}{\prod_{\ell=1}^L\Gamma\left(\frac{N_\ell}{2}\right)} \int_{\mathbb R^{P}} dt \exp\left[-\frac{\left|\left|t\right|\right|^2}{2\beta}+i\theta_*^TXt\right]~ \ensuremath{G_{L,1}^{1,L}\left( M\|Xt + x\|^2 ~\bigg| \begin{array}{c}
     1-\frac{N_L}{2},\dots,1-\frac{N_1}{2}  \\
     0 
\end{array} \right)},
\end{align}
where 
\[
4M =  \prod_{\ell=0}^L \frac{2\sigma^2}{N_\ell}.
\]
To complete the proof of Proposition \ref{prop:Z-gen}, we write




\[
x = x_{||}+x_{\perp},\qquad x_{||}\in \mathrm{col}(X),\quad x_{\perp}\in \mathrm{col}(X)^\perp.
\]





Note that $X$ gives an isomorphism from $\mathbb R^P$ to $\mathrm{im}{(X)}$. Thus, we may change variables to write $Z_\beta(x)$ as
\begin{align*}
\prod_{\ell=1}^L\Gamma\left(\frac{N_\ell}{2}\right)^{-1} \int_{\mathbb R^{P}} d\zeta\exp\left[-\frac{\left|\left|X^{\dagger}\zeta\right|\right|^2}{2\beta}+i\theta_*^T\zeta\right]~ \ensuremath{G_{L,1}^{1,L}\left( M\|\zeta + x\|^2 ~\bigg| \begin{array}{c}
     1-\frac{{\bf N}}{2}  \\
     0 
\end{array} \right)},
\end{align*}
where $X^{\dagger}$ the pseudo-inverse of $X$. Finally, note that
\[
\left|\left|\zeta+x\right|\right|^2 = \left|\left|\zeta + x_{||}\right|\right|^2 + \left|\left|x_\perp\right|\right|^2 .
\]
Hence, changing variables to $\tau = \zeta + x_{||}$ yields the following expression for $Z_\beta(x)$:
\begin{align*}
&\prod_{\ell=1}^L\Gamma\left(\frac{N_\ell}{2}\right)^{-1} \exp\left[-i\theta_*^Tx_{||}\right]\times \int_{\mathrm{col}{(X)}} d\zeta\exp\left[-\frac{\left|\left|X^{\dagger}(\tau - x_{||})\right|\right|^2}{2\beta}+i\theta_*^T\zeta\right]~ \ensuremath{G_{L,1}^{1,L}\left( M\left|\left|\zeta\right|\right|^2 +M\left|\left|x_\perp\right|\right|^2 ~\bigg| \begin{array}{c}
     1-\frac{{\bf N}}{2}  \\
     0 
\end{array} \right)}.
\end{align*}
This is precisely the statement of Proposition \ref{prop:Z-gen}.

